#!/bin/sh
full_diagnostics(){ out="$REPORT_DIR/diagnostics-$(date +%Y%m%d-%H%M%S).txt"; { echo "iSH-AOK Config diagnostics"; date; uname -a; echo; cat /etc/os-release 2>/dev/null; echo '\n== Filesystem =='; df -h; mount; echo '\n== Memory =='; cat /proc/meminfo 2>/dev/null; echo '\n== Package manager =='; echo "$PKG_MGR"; echo '\n== Init =='; echo "$INIT_SYSTEM"; echo '\n== Repositories =='; find /etc -maxdepth 3 \( -name sources.list -o -name '*.list' -o -name repositories -o -name mirrorlist \) -type f -exec sh -c 'echo --- $1; cat "$1"' sh {} \; 2>/dev/null; echo '\n== Shell syntax =='; for f in "$CURRENT_HOME/.profile" "$CURRENT_HOME/.bashrc" "$CURRENT_HOME/.zshrc"; do [ -f "$f" ] && sh -n "$f" 2>&1; done; echo '\n== SSH =='; ssh -V 2>&1; sshd -T 2>&1 | head -100; echo '\n== Services =='; ps aux 2>/dev/null; echo '\n== AOK =='; grep aokfs /proc/mounts 2>/dev/null; ls -la /opt/AOK 2>/dev/null; } >"$out" 2>&1; ui_text Diagnostics "$(tail -n 300 "$out")\n\nFull report: $out"; }
diagnostics_full_menu(){ while :; do c=$(ui_menu 'Comprehensive diagnostics' 'Health checks and report generation.' full 'Generate full diagnostic report' repos 'Repository health' packages 'Package-manager health' shell 'Shell syntax checks' ssh 'SSH validation' services 'Service failures' links 'Broken symlinks' permissions 'Permission audit' arch 'Binary architecture scan' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in full) full_diagnostics;; repos) run_capture Repositories pkg_update;; packages) run_capture Packages sh -c 'command -v dpkg >/dev/null && dpkg --audit; command -v apk >/dev/null && apk audit --system; command -v pacman >/dev/null && pacman -Dk';; shell) run_capture Shell sh -c "for f in '$CURRENT_HOME/.profile' '$CURRENT_HOME/.bashrc' '$CURRENT_HOME/.zshrc' '$CURRENT_HOME/.ashrc'; do test -f \"\$f\" && { echo ===\$f; sh -n \"\$f\"; }; done";; ssh) run_capture SSH sh -c 'sshd -t 2>&1; ssh -G localhost >/dev/null 2>&1; echo client:$?';; services) run_capture Services sh -c 'rc-status --crashed 2>/dev/null || systemctl --failed 2>/dev/null || service --status-all 2>/dev/null';; links) run_capture Symlinks find /etc /usr/local "$CURRENT_HOME" -xtype l -print;; permissions) security_report;; arch) r=$(ui_input Architecture 'Path' /usr/local/bin) || continue; run_capture Architecture sh -c "find '$r' -type f -perm -111 -exec file {} + 2>/dev/null | grep -v text";; back) return;; esac; done; }
